CREATE TRIGGER ai_usage_reservation_apply AFTER INSERT ON financial_usage_events WHEN new.decision='allowed' AND new.reservation_mode='atomic' BEGIN
 UPDATE financial_provider_quotas SET quota_used=quota_used+new.units,updated_at=new.created_at WHERE id=new.quota_id;
END;
CREATE TRIGGER ai_usage_reservation_guard BEFORE INSERT ON financial_usage_events WHEN new.decision='allowed' AND new.reservation_mode='atomic' BEGIN
 SELECT RAISE(ABORT,'ai_quota_reservation_conflict') WHERE NOT EXISTS (
  SELECT 1 FROM financial_provider_quotas WHERE id=new.quota_id AND vendor_id=new.vendor_id AND status IN ('active','warning') AND quota_total IS NOT NULL AND (quota_used+new.units<=quota_total OR hard_stop_before_paid=0)
 );
 SELECT RAISE(ABORT,'ai_budget_reservation_conflict') WHERE NOT EXISTS (
  SELECT 1 FROM financial_agent_provider_policies p WHERE p.agent_slug=new.agent_slug AND p.vendor_id=new.vendor_id AND p.status='active'
   AND (p.max_request_cost_minor IS NULL OR new.estimated_cost_minor<=p.max_request_cost_minor)
   AND (p.daily_budget_minor IS NULL OR new.estimated_cost_minor+COALESCE((SELECT SUM(u.estimated_cost_minor) FROM financial_usage_events u WHERE u.agent_slug=new.agent_slug AND u.vendor_id=new.vendor_id AND u.decision='allowed' AND u.created_at>=CAST(strftime('%s',new.created_at/1000,'unixepoch','start of day') AS INTEGER)*1000),0)<=p.daily_budget_minor)
   AND (p.monthly_budget_minor IS NULL OR new.estimated_cost_minor+COALESCE((SELECT SUM(u.estimated_cost_minor) FROM financial_usage_events u WHERE u.agent_slug=new.agent_slug AND u.vendor_id=new.vendor_id AND u.decision='allowed' AND u.created_at>=CAST(strftime('%s',new.created_at/1000,'unixepoch','start of month') AS INTEGER)*1000),0)<=p.monthly_budget_minor)
 );
 SELECT RAISE(ABORT,'ai_budget_reservation_conflict') WHERE EXISTS (
  SELECT 1 FROM financial_budgets b WHERE b.status='active' AND b.category IN ('general','ai') AND b.period_start<=new.created_at AND b.period_end>new.created_at AND (b.agent_slug IS NULL OR b.agent_slug=new.agent_slug)
   AND new.estimated_cost_minor+COALESCE((SELECT SUM(u.estimated_cost_minor) FROM financial_usage_events u WHERE u.decision='allowed' AND u.created_at>=b.period_start AND u.created_at<b.period_end AND (b.agent_slug IS NULL OR u.agent_slug=b.agent_slug)),0)>b.limit_minor
 );
END;
CREATE TRIGGER document_assignment_beneficiary BEFORE INSERT ON document_assignments
 WHEN (NEW.project_id IS NOT NULL AND (SELECT client_id FROM projects WHERE id=NEW.project_id) IS NOT (SELECT beneficiary_id FROM documents WHERE id=NEW.document_id))
 OR (NEW.service_id IS NOT NULL AND (SELECT p.client_id FROM services s JOIN projects p ON p.id=s.project_id WHERE s.id=NEW.service_id) IS NOT (SELECT beneficiary_id FROM documents WHERE id=NEW.document_id))
 OR (NEW.subscription_id IS NOT NULL AND (SELECT client_id FROM subscriptions WHERE id=NEW.subscription_id) IS NOT (SELECT beneficiary_id FROM documents WHERE id=NEW.document_id))
 OR (NEW.partner_client_id IS NOT NULL AND NEW.partner_client_id IS NOT (SELECT beneficiary_id FROM documents WHERE id=NEW.document_id))
 BEGIN SELECT RAISE(ABORT,'document_beneficiary_mismatch'); END;
CREATE TRIGGER document_assignment_immutable BEFORE UPDATE ON document_assignments BEGIN SELECT RAISE(ABORT,'document_assignment_immutable'); END;
CREATE TRIGGER document_billing_assignment_integrity BEFORE INSERT ON document_billing_preparations
WHEN EXISTS(SELECT 1 FROM document_assignments a LEFT JOIN projects p ON p.id=a.project_id LEFT JOIN services sv ON sv.id=a.service_id LEFT JOIN projects sp ON sp.id=sv.project_id LEFT JOIN subscriptions sub ON sub.id=a.subscription_id WHERE a.document_id=NEW.document_id AND ((a.project_id IS NOT NULL AND p.client_id IS NOT NEW.client_id) OR (a.service_id IS NOT NULL AND sp.client_id IS NOT NEW.client_id) OR (a.subscription_id IS NOT NULL AND sub.client_id IS NOT NEW.client_id)))
 OR EXISTS(SELECT 1 FROM financial_revenues r JOIN projects p ON p.id=r.project_id WHERE r.id=NEW.revenue_id AND p.client_id IS NOT NEW.client_id)
BEGIN SELECT RAISE(ABORT,'document_billing_source_changed'); END;
CREATE TRIGGER document_billing_source_integrity BEFORE INSERT ON document_billing_preparations
WHEN NOT EXISTS(SELECT 1 FROM document_versions v JOIN documents d ON d.id=v.document_id JOIN document_approvals a ON a.version_id=v.id WHERE v.id=NEW.version_id AND d.id=NEW.document_id AND d.beneficiary_id=NEW.client_id AND d.scope='client' AND d.current_version_id=v.id AND d.archived_at IS NULL)
 OR NOT EXISTS(SELECT 1 FROM financial_revenues r WHERE r.id=NEW.revenue_id AND r.client_id=NEW.client_id AND r.status='draft')
BEGIN SELECT RAISE(ABORT,'document_billing_source_changed'); END;
CREATE TRIGGER financial_receipt_apply AFTER INSERT ON financial_receipts BEGIN
  UPDATE financial_revenues SET
    status=(CASE WHEN (SELECT SUM(amount_minor) FROM financial_receipts WHERE revenue_id=NEW.revenue_id)=gross_amount_minor THEN 'paid' ELSE 'partially_paid' END),
    payment_date=(SELECT MAX(paid_at) FROM financial_receipts WHERE revenue_id=NEW.revenue_id),
    updated_at=NEW.created_at,updated_by=NEW.created_by
    WHERE id=NEW.revenue_id;
END;
CREATE TRIGGER financial_receipt_no_delete BEFORE DELETE ON financial_receipts
  BEGIN SELECT RAISE(ABORT,'receipt_immutable'); END;
CREATE TRIGGER financial_receipt_no_update BEFORE UPDATE ON financial_receipts
  BEGIN SELECT RAISE(ABORT,'receipt_immutable'); END;
CREATE TRIGGER financial_receipt_preserve_document BEFORE UPDATE OF currency,gross_amount_minor ON financial_revenues
  WHEN EXISTS(SELECT 1 FROM financial_receipts WHERE revenue_id=OLD.id)
    AND (NEW.currency IS NOT OLD.currency OR NEW.gross_amount_minor IS NOT OLD.gross_amount_minor)
  BEGIN SELECT RAISE(ABORT,'reconciled_document_amount_locked'); END;
CREATE TRIGGER financial_receipt_preserve_state BEFORE UPDATE OF status,payment_date ON financial_revenues
  WHEN EXISTS(SELECT 1 FROM financial_receipts WHERE revenue_id=OLD.id)
    AND (NEW.status IS NOT CASE
      WHEN (SELECT SUM(amount_minor) FROM financial_receipts WHERE revenue_id=OLD.id)=NEW.gross_amount_minor
        THEN 'paid' ELSE 'partially_paid' END
      OR NEW.payment_date IS NOT (SELECT MAX(paid_at) FROM financial_receipts WHERE revenue_id=OLD.id))
  BEGIN SELECT RAISE(ABORT,'reconciled_document_state_locked'); END;
CREATE TRIGGER financial_receipt_validate BEFORE INSERT ON financial_receipts BEGIN
  SELECT RAISE(ABORT,'receipt_revenue_not_payable') WHERE NOT EXISTS(SELECT 1 FROM financial_revenues WHERE id=NEW.revenue_id AND archived_at IS NULL
    AND status IN ('invoiced','sent','partially_paid','overdue') AND currency=NEW.currency AND gross_amount_minor IS NOT NULL);
  SELECT RAISE(ABORT,'receipt_exceeds_balance') WHERE NEW.amount_minor + COALESCE((SELECT SUM(amount_minor) FROM financial_receipts WHERE revenue_id=NEW.revenue_id),0)
    > (SELECT gross_amount_minor FROM financial_revenues WHERE id=NEW.revenue_id);
END;
CREATE TRIGGER financial_subscription_revision AFTER UPDATE ON financial_expenses
WHEN NEW.subscription_revision=OLD.subscription_revision
BEGIN UPDATE financial_expenses SET subscription_revision=OLD.subscription_revision+1 WHERE id=NEW.id; END;
CREATE TRIGGER hub_documents_delete AFTER DELETE ON hub_documents BEGIN
 INSERT INTO hub_documents_fts(hub_documents_fts,rowid,title,content_text) VALUES('delete',old.rowid,old.title,old.content_text);
END;
CREATE TRIGGER hub_documents_insert AFTER INSERT ON hub_documents BEGIN
 INSERT INTO hub_documents_fts(rowid,title,content_text) VALUES(new.rowid,new.title,new.content_text);
END;
CREATE TRIGGER hub_documents_update AFTER UPDATE OF title,content_text ON hub_documents BEGIN
 INSERT INTO hub_documents_fts(hub_documents_fts,rowid,title,content_text) VALUES('delete',old.rowid,old.title,old.content_text);
 INSERT INTO hub_documents_fts(rowid,title,content_text) VALUES(new.rowid,new.title,new.content_text);
END;
CREATE TRIGGER maintenance_beneficiary_insert BEFORE INSERT ON subscriptions WHEN NEW.maintenance_enabled=1 AND NEW.client_id<>(SELECT p.client_id FROM services v JOIN projects p ON p.id=v.project_id WHERE v.id=NEW.service_id) BEGIN SELECT RAISE(ABORT,'maintenance_beneficiary_mismatch'); END;
CREATE TRIGGER maintenance_beneficiary_update BEFORE UPDATE OF client_id,service_id,maintenance_enabled ON subscriptions WHEN NEW.maintenance_enabled=1 AND NEW.client_id<>(SELECT p.client_id FROM services v JOIN projects p ON p.id=v.project_id WHERE v.id=NEW.service_id) BEGIN SELECT RAISE(ABORT,'maintenance_beneficiary_mismatch'); END;
CREATE TRIGGER operation_appointment_insert BEFORE INSERT ON operation_records WHEN new.kind='appointment' BEGIN
 SELECT RAISE(ABORT,'appointment_invalid') WHERE new.assignee_id IS NULL OR new.starts_at IS NULL OR new.due_at IS NULL OR new.due_at<=new.starts_at;
 SELECT RAISE(ABORT,'appointment_overlap') WHERE new.archived_at IS NULL AND new.status NOT IN ('cancelled','done') AND EXISTS (
  SELECT 1 FROM operation_records WHERE kind='appointment' AND archived_at IS NULL AND status NOT IN ('cancelled','done') AND assignee_id=new.assignee_id AND starts_at<new.due_at AND due_at>new.starts_at
 );
END;
CREATE TRIGGER operation_appointment_update BEFORE UPDATE ON operation_records WHEN new.kind='appointment' BEGIN
 SELECT RAISE(ABORT,'appointment_invalid') WHERE new.assignee_id IS NULL OR new.starts_at IS NULL OR new.due_at IS NULL OR new.due_at<=new.starts_at;
 SELECT RAISE(ABORT,'appointment_overlap') WHERE new.archived_at IS NULL AND new.status NOT IN ('cancelled','done') AND EXISTS (
  SELECT 1 FROM operation_records WHERE id!=new.id AND kind='appointment' AND archived_at IS NULL AND status NOT IN ('cancelled','done') AND assignee_id=new.assignee_id AND starts_at<new.due_at AND due_at>new.starts_at
 );
END;
CREATE TRIGGER project_chat_beneficiary BEFORE UPDATE OF client_id ON projects WHEN NEW.client_id IS NOT OLD.client_id AND EXISTS(SELECT 1 FROM staff_chat_messages m WHERE m.project_id=OLD.id) BEGIN SELECT RAISE(ABORT,'project_chat_history'); END;
CREATE TRIGGER project_chat_context_immutable BEFORE UPDATE OF project_id,recipient_id,channel,author_id ON staff_chat_messages BEGIN SELECT RAISE(ABORT,'chat_context_immutable'); END;
CREATE TRIGGER project_chat_room_scope BEFORE INSERT ON staff_chat_messages WHEN NEW.project_id IS NOT NULL AND (NEW.recipient_id IS NOT NEW.author_id OR NEW.channel<>'general') BEGIN SELECT RAISE(ABORT,'invalid_project_chat_scope'); END;
CREATE TRIGGER subscription_allocation_beneficiary_insert BEFORE INSERT ON subscriptions
WHEN NEW.allocation_key IS NOT NULL AND NEW.client_id IS NOT (SELECT p.client_id FROM services v JOIN projects p ON p.id=v.project_id WHERE v.id=NEW.service_id)
BEGIN SELECT RAISE(ABORT,'subscription_allocation_beneficiary_mismatch'); END;
CREATE TRIGGER subscription_allocation_beneficiary_update BEFORE UPDATE OF client_id,service_id,allocation_key ON subscriptions
WHEN NEW.allocation_key IS NOT NULL AND NEW.client_id IS NOT (SELECT p.client_id FROM services v JOIN projects p ON p.id=v.project_id WHERE v.id=NEW.service_id)
BEGIN SELECT RAISE(ABORT,'subscription_allocation_beneficiary_mismatch'); END;
CREATE TRIGGER survey_follow_lead_conversion AFTER UPDATE OF converted_project_id ON leads
WHEN NEW.converted_project_id IS NOT NULL AND NEW.converted_project_id IS NOT OLD.converted_project_id
BEGIN
 UPDATE surveys SET project_id=NEW.converted_project_id,
 client_id=(SELECT client_id FROM projects WHERE id=NEW.converted_project_id),
 organization_id=(SELECT organization_id FROM projects WHERE id=NEW.converted_project_id),
 revision=revision+1,updated_at=CAST(strftime('%s','now') AS INTEGER)*1000
 WHERE lead_id=NEW.id AND (project_id IS NULL OR project_id=OLD.converted_project_id);
 UPDATE hub_documents SET project_id=NEW.converted_project_id,
 client_id=(SELECT client_id FROM projects WHERE id=NEW.converted_project_id)
 WHERE id IN(SELECT b.document_id FROM survey_briefs b JOIN surveys s ON s.id=b.survey_id WHERE s.lead_id=NEW.id AND s.project_id=NEW.converted_project_id);
END;
CREATE TRIGGER visual_asset_context_immutable BEFORE UPDATE OF scope,client_id,project_id,object_key,sha256,file_name,content_type,size_bytes,created_by ON visual_assets BEGIN SELECT RAISE(ABORT,'visual_asset_context_immutable'); END;
CREATE TRIGGER visual_asset_parent_beneficiary BEFORE UPDATE OF client_id ON projects WHEN NEW.client_id<>OLD.client_id AND EXISTS(SELECT 1 FROM visual_assets a WHERE a.project_id=OLD.id) BEGIN SELECT RAISE(ABORT,'client_workspace_asset_history'); END;
CREATE TRIGGER visual_asset_project_client_insert BEFORE INSERT ON visual_assets WHEN NEW.project_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM projects p WHERE p.id=NEW.project_id AND p.client_id=NEW.client_id) BEGIN SELECT RAISE(ABORT,'visual_asset_beneficiary_mismatch'); END;
CREATE TRIGGER project_client_cannot_clear BEFORE UPDATE OF client_id ON projects WHEN OLD.client_id IS NOT NULL AND NEW.client_id IS NULL BEGIN SELECT RAISE(ABORT,'client_workspace_client_required'); END;
